{
  "name": "串口通信接口组件",
  "name_en": "Serial Communication Interface Component",
  "manufacturer": "Zahner",
  "description": "用于实验控制软件的非物理串口通信组件，提供命令/数据串口的连接、写入、关闭和通信日志记录功能，常用于通过 SCPI 与仪器进行通信和调试。",
  "description_en": "A non-physical serial communication component used in laboratory control software. It provides command/data serial port connection, writing, closing, and communication log functions, and is commonly used for SCPI-based instrument communication and debugging.",
  "actions": [
    {
      "action_name": "auto-connect",
      "description": "连接到指定串口接口。",
      "description_en": "Connect to the specified serial interface."
    },
    {
      "action_name": "auto-isConnected",
      "description": "检查串口接口是否已连接。",
      "description_en": "Check whether the serial interface is connected."
    },
    {
      "action_name": "auto-write",
      "description": "向串口接口写入字节数据。",
      "description_en": "Write byte data to the serial interface."
    },
    {
      "action_name": "auto-close",
      "description": "关闭串口连接。",
      "description_en": "Close the serial connection."
    },
    {
      "action_name": "auto-writeLog",
      "description": "记录串口通信日志，包括收发方向和时间信息。",
      "description_en": "Record serial communication logs, including direction and timestamp information."
    },
    {
      "action_name": "auto-getDebugString",
      "description": "获取用于调试的串口通信日志文本。",
      "description_en": "Get the serial communication log text for debugging."
    },
    {
      "action_name": "auto-getLastCommandWithAnswer",
      "description": "获取最近一次命令及其响应记录。",
      "description_en": "Get the most recent command and its response record."
    }
  ],
  "tag_hints": [
    "serial communication",
    "SCPI control",
    "instrument command logging",
    "serial port connection",
    "debug trace",
    "command/data interface"
  ]
}

